# Treat both 5 and 9 as boundaries
def bfs_fill_treated_as_open(grid, filled_with, allowed_values, h, w):
    """BFS - cells with allowed_values are "open", others are "walls/filled"
    Returns set of reachable positions starting from filled_with"""
    start_pos = tuple(filled_with)

    if 0 <= start_pos[0] < h and 0 <= start_pos[1] < w:
        visited = set([start_pos])
        queue = deque([start_pos])

        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in visited:
                    if grid[nr, nc] in allowed_values:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
        return visited
    return set()

