def find_pockets(grid_dict, wall_values, h, w):
    """Find regions of non-wall, non-background cells that are completely enclosed"""
    # Background is 0, any other value is "different"

    # Find all "different" cells (not 0)
    different_cells = set()
    for r in range(h):
        for c in range(w):
            if grid_dict[(r, c)] != 0:
                different_cells.add((r, c))

    # For each pocket cell, check if it's reachable from the border
    border_cells = []
    for val in grid_dict.values():
        if val == 0:
            # Check if this 0 is on border, or find a path from border
            # (simplified: just mark corner 0s as border-connected)
            pass

    # Actually better: flood fill 0s from border and mark all that are connected

    visited_from_border = set()
    # Start from all border 0s
    queue = deque()
    for c in range(w):
        if grid_dict[(0, c)] == 0:
            queue.append((0, c))
            visited_from_border.add((0, c))
    for c in range(w):
        if grid_dict[(h-1, c)] == 0:
            queue.append((h-1, c))
            visited_from_border.add((h-1, c))
    for r in range(h):
        if grid_dict[(r, 0)] == 0:
            queue.append((r, 0))
            visited_from_border.add((r, 0))
        if grid_dict[(r, w-1)] == 0:
            queue.append((r, w-1))
            visited_from_border.add((r, w-1))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in visited_from_border:
                    if (nr, nc) not in different_cells and grid_dict[(nr, nc)] == 0:
