def find_connected_components(grid, target_value):
    """Find all connected components of a value in the grid"""
    h, w = grid.shape
    visited = np.zeros((h, w), dtype=bool)
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r, c] == target_value and not visited[r, c]:
                comp = set()
                queue = deque([(r, c)])
                visited[r, c] = True
                while queue:
                    cr, cc = queue.popleft()
                    comp.add((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr, nc] == target_value and not visited[nr, nc]:
                            visited[nr, nc] = True
                            queue.append((nr, nc))
                components.append(comp)
    return components

